import { pgTableCreator, text, timestamp, uuid, integer, jsonb, boolean, index, uniqueIndex } from "drizzle-orm/pg-core"

import type { RunStatus } from "@/server/domain/errors"

/**
 * The cloud control plane's own tables.
 *
 * Better Auth's tables live in `auth-tables.ts` and are generated by its CLI,
 * so they are never edited here. Everything below is ours.
 *
 * The shape is driven by one question: what does a hosted runtime need to be
 * told about a run when the browser tab that started it has long since closed?
 * An agent that lives in a Boat sandbox is a separate machine — it has its own
 * filesystem, its own lifetime, and its own failure modes — so control-plane
 * state has to be the source of truth for all three.
 */

const table = pgTableCreator((name) => `nah_${name}`)

export const agents = table(
  "agents",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** The Better Auth organisation that owns and pays for this agent. */
    organizationId: text("organization_id").notNull(),
    name: text("name").notNull(),
    /** The repo or nothing: an agent is defined by the project it edits. */
    repository: text("repository").notNull(),
    /**
     * The Boat template a sandbox forks from.
     *
     * A template, not an image: a Boat sandbox boots from a stopped snapshot,
     * and a good one already has the `nah` daemon installed as a systemd unit
     * (see `docs/hosted-runtime-on-boat.md` §3.4). Forks land in seconds at
     * roughly constant cost, so this is the whole cold-start budget.
     */
    template: text("template").notNull().default("nah-runtime-base"),
    /** Opaque blob: env secrets, model choice, resource ceilings. */
    config: jsonb("config").$type<AgentConfig>().notNull().default({}),
    /** A paused agent keeps its filesystem but uses no CPU. */
    paused: boolean("paused").notNull().default(false),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow()
  },
  (t) => [index("agents_org_idx").on(t.organizationId)]
)

export const runs = table(
  "runs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    agentId: uuid("agent_id")
      .notNull()
      .references(() => agents.id, { onDelete: "cascade" }),
    organizationId: text("organization_id").notNull(),
    status: text("status").$type<RunStatus>().notNull().default("queued"),
    /** The user's prompt. Frozen at creation so a replay is faithful. */
    prompt: text("prompt").notNull(),
    /** The Boat sandbox id, once one has been assigned. */
    sandboxId: text("sandbox_id"),
    /** Exit code of the agent process; null while it is still running. */
    exitCode: integer("exit_code"),
    /** Model tokens consumed, for the usage ledger and the cost estimate. */
    tokensIn: integer("tokens_in"),
    tokensOut: integer("tokens_out"),
    error: text("error"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    startedAt: timestamp("started_at", { withTimezone: true }),
    finishedAt: timestamp("finished_at", { withTimezone: true })
  },
  (t) => [
    index("runs_agent_idx").on(t.agentId),
    index("runs_org_idx").on(t.organizationId),
    index("runs_status_idx").on(t.status)
  ]
)

/**
 * Every append-only event a run produced.
 *
 * The terminal UI is a pure function of this table: replay the rows for a run
 * and you redraw the screen. That is what makes the TUI work against a remote
 * sandbox — it does not hold the transcript in memory, it reads it back.
 */
export const runEvents = table(
  "run_events",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    runId: uuid("run_id")
      .notNull()
      .references(() => runs.id, { onDelete: "cascade" }),
    /** Monotonic within a run, so the client can drop duplicates and gaps. */
    sequence: integer("sequence").notNull(),
    kind: text("kind").notNull(),
    payload: jsonb("payload").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow()
  },
  (t) => [
    uniqueIndex("run_events_seq_idx").on(t.runId, t.sequence),
    index("run_events_run_idx").on(t.runId)
  ]
)

/**
 * An opaque handle onto a sandbox's filesystem.
 *
 * Not the contents: the files live on the Boat VM's own disk. This row exists so
 * an organisation can list and name the sandboxes it owns without every listing
 * call making a round trip to the provider.
 *
 * `status` is a local mirror of Boat's sandbox state, not the authority — the
 * provider is. It exists so a list view is one query instead of N, and so a
 * sandbox that vanished provider-side still shows as `destroyed` rather than
 * silently dropping out of the dashboard. Webhooks are what keep it honest.
 */
export const sandboxes = table(
  "sandboxes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id").notNull(),
    agentId: uuid("agent_id").references(() => agents.id, { onDelete: "set null" }),
    /** The addressable id Boat gave us — the one every SDK call takes. */
    boatSandboxId: text("boat_sandbox_id").notNull(),
    status: text("status").$type<SandboxStatus>().notNull().default("starting"),
    /**
     * The daemon's HTTPS endpoint, from `host <port> --private`.
     *
     * `null` until the sandbox is reachable. Worth storing rather than
     * re-deriving per call: a stopped Boat sandbox keeps its URL, so resume does
     * not re-resolve it, and a run that outlives the browser tab still knows
     * where to reconnect.
     */
    runtimeUrl: text("runtime_url"),
    /** Bytes written, for the storage quota shown in the dashboard. */
    bytesUsed: integer("bytes_used").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    destroyedAt: timestamp("destroy_at", { withTimezone: true })
  },
  (t) => [
    uniqueIndex("sandboxes_boat_id_idx").on(t.boatSandboxId),
    index("sandboxes_org_idx").on(t.organizationId)
  ]
)

/**
 * Billable usage, written after a run settles and never updated in place.
 *
 * Append-only on purpose: a metering row that can be edited is a metering row
 * that will be, and the audit trail is the only reason a bill is arguable.
 */
export const usageLedger = table(
  "usage",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id").notNull(),
    runId: uuid("run_id").references(() => runs.id, { onDelete: "set null" }),
    tokens: integer("tokens").notNull(),
    /** Millicpu-seconds billed, so a run that did nothing is still not free. */
    computeMs: integer("compute_ms").notNull(),
    storageBytes: integer("storage_bytes").notNull(),
    recordedAt: timestamp("recorded_at", { withTimezone: true }).notNull().defaultNow()
  },
  (t) => [index("usage_org_idx").on(t.organizationId, t.recordedAt)]
)

/**
 * What a caller may configure on an agent; never credentials.
 *
 * `noEnv` is here because it is the one field that is easy to leave unset and
 * expensive to get wrong. Boat injects account-level keys into every sandbox by
 * default; a hosted run must opt out explicitly or our model credentials end up
 * in a user-reachable VM. See `docs/hosted-runtime-on-boat.md` §3.4.
 */
export interface AgentConfig {
  readonly model?: string
  readonly env?: Readonly<Record<string, string>>
  /** vCPU count. Boat bills per second of it, so this is the cost dial. */
  readonly cpu?: number
  readonly memoryMb?: number
  readonly timeoutMs?: number
  /** Defaults true. Only a trusted internal caller may ever set it false. */
  readonly noEnv?: boolean
}

/**
 * A sandbox's lifecycle, as this control plane mirrors it.
 *
 * `stopped` is the important one: on Boat a stopped sandbox keeps its disk and
 * snapshots for free, so it is a billing state and not a teardown. `destroyed`
 * is the only terminal state here, and it is the only one that frees the disk.
 */
export type SandboxStatus =
  | "starting"
  | "running"
  | "stopped"
  | "destroyed"

export const SANDBOX_STATUSES = [
  "starting",
  "running",
  "stopped",
  "destroyed"
] as const satisfies readonly SandboxStatus[]

export type Agent = typeof agents.$inferSelect
export type NewAgent = typeof agents.$inferInsert
export type Run = typeof runs.$inferSelect
export type RunEvent = typeof runEvents.$inferSelect
export type Sandbox = typeof sandboxes.$inferSelect